entries.syntax_block:
Colour = New Colour(255, 128, 0);
Colour = New Colour("#FF8000");
Colour = New Colour("orange");

entries.example:
Area = Doc.Area(1, 1);
Area.BackgroundColour = New Colour("#FFF2CC");
Area.TextColour = New Colour(192, 0, 0);
Message(String(Area.TextColour));   // 192,0,0

Area = Doc.Area(1, 1);
Area.Font = New Font("Arial,90,700,12,70,0");   // Arial, жирний, 12 пунктів
F = Area.Font;      // копія
F.Underlined = True;
Area.Font = F;      // присвоєно назад

F = Area.Font;
F.Style = 93;   // курсив
Area.Font = F;

F = Area.Font;
F.Weight = 700;   // жирний
Area.Font = F;

F = Area.Font;
F.Underlined = True;
Area.Font = F;

F = Area.Font;
F.Face = "Courier New";
F.Family = 76;   // моноширинний, якщо гарнітури немає
Area.Font = F;

P = New Point(10, 20);
P.Left = P.Left + 5;
Message(String(P));   // 15,20

S = Area.Size;      // копія
S.Height = S.Height * 2;
Area.Size = S;      // присвоєно назад
